PRAGMA recursive_triggers=OFF; CREATE TEMP TABLE tbl(a,b); INSERT INTO tbl VALUES(1,2); INSERT INTO tbl VALUES(3,4); CREATE TEMP TRIGGER before_update_row BEFORE UPDATE ON tbl FOR EACH ROW BEGIN INSERT INTO rlog VALUES((SELECT coalesce(max(idx),0)+1 FROM rlog),old.a,old.b,(SELECT coalesce(sum(a),0) FROM tbl),(SELECT coalesce(sum(b),0) FROM tbl),new.a,new.b); END; CREATE TEMP TRIGGER after_update_row AFTER UPDATE ON tbl FOR EACH ROW BEGIN INSERT INTO rlog VALUES((SELECT coalesce(max(idx),0)+1 FROM rlog),old.a,old.b,(SELECT coalesce(sum(a),0) FROM tbl),(SELECT coalesce(sum(b),0) FROM tbl),new.a,new.b); END; CREATE TEMP TRIGGER conditional_update_row AFTER UPDATE ON tbl FOR EACH ROW WHEN old.a=1 BEGIN INSERT INTO clog VALUES((SELECT coalesce(max(idx),0)+1 FROM clog),old.a,old.b,(SELECT coalesce(sum(a),0) FROM tbl),(SELECT coalesce(sum(b),0) FROM tbl),new.a,new.b); END; UPDATE tbl SET a=a*10,b=b*10;